'use strict';
// Serverless hosting has no durable local filesystem. Keep each user's state on-device.
const browserStorageMode=!['localhost','127.0.0.1','[::1]'].includes(location.hostname)||new URLSearchParams(location.search).has('browser-storage');
if(browserStorageMode){
 const hostedReadFile=readFile;readFile=async function(file){if(file?.type==='application/pdf'&&file.size>4*1024*1024)throw Error('Для Vercel виберіть PDF розміром до 4 МБ.');return hostedReadFile(file)};
 const browserDatabase=new Promise((resolve,reject)=>{const request=indexedDB.open('mono-hosted-state',1);request.onupgradeneeded=()=>request.result.createObjectStore('records');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)});
 async function browserRecord(mode,update){const database=await browserDatabase;return new Promise((resolve,reject)=>{const transaction=database.transaction('records',mode),store=transaction.objectStore('records'),request=store.get('state');let result;request.onsuccess=()=>{try{result=update?update(request.result):request.result;if(update)store.put(result,'state')}catch(error){reject(error);transaction.abort()}};transaction.oncomplete=()=>resolve(result);transaction.onerror=()=>reject(transaction.error);transaction.onabort=()=>reject(transaction.error||Error('Storage aborted'))})}
 loadSharedState=async function(force=false){if(sharedLoading||sharedSaving||(!force&&(document.querySelector('#modal').open||document.documentElement.dataset.gesture==='active'||document.documentElement.dataset.editing==='true')))return;sharedLoading=true;try{const record=await browserRecord('readonly');if(record&&(force||record.revision!==serverRevision)){const next=await hydrateState(record.state);state=next;serverRevision=record.revision;if(!loading)render()}document.documentElement.dataset.storage='saved'}catch(e){document.documentElement.dataset.storage='offline';throw Error('Не вдалося відкрити сховище браузера. Дозвольте збереження даних для сайту.')}finally{sharedLoading=false}};
 persist=async function(){sharedSaving=true;document.documentElement.dataset.storage='saving';try{const value=await serializeState(),expected=serverRevision;const record=await browserRecord('readwrite',current=>{if(current&&current.revision!==expected){const error=Error('Дані змінились в іншій вкладці. Оновіть сторінку.');error.conflict=true;throw error}return {revision:(current?.revision||0)+1,state:value}});serverRevision=record.revision;document.documentElement.dataset.storage='saved'}finally{sharedSaving=false}};
 const hostedFetch=window.fetch.bind(window);window.fetch=async function(input,options){const url=new URL(typeof input==='string'?input:input.url,location.href);if(url.origin===location.origin&&url.pathname==='/api/statement.xlsx'&&(!options?.method||options.method==='GET')){const value=await serializeState();value.files=[];value.avatar=null;return hostedFetch('/api/statement.xlsx',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({state:value,query:Object.fromEntries(url.searchParams)})})}return hostedFetch(input,options)};
}
